pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Bin utilization
    score += ((bin_capacity - bin_residual) as f64 / bin_capacity as f64).powf(1.5);

    // Fitting bins count penalty
    if fitting_bins_count == 0 { score -= 2.5; }

    // Post-residual bonus/penalty
    if post_residual < 10 { score += 3.0; }
    else if post_residual < 30 { score += 1.5; }
    else { score -= 1.0; }

    // Future item size compatibility
    if next_item_size > 0 && post_residual + next_item_size > bin_capacity / 4 { score -= 2.0; }

    // Open bins count bonus
    score += (open_bins_count as f64 / total_items as f64) * 3.0;

    // Post-residual relative to mean residual
    if post_residual < next_item_size { score -= 1.5; }
    if post_residual > mean_residual / 2.0 && post_residual < mean_residual * 2.0 { score += 1.0; }

    // Additional lookahead penalty
    if step_index < total_items / 2 {
        if post_residual < next_item_size / 2 { score -= 0.5; }
        if post_residual > mean_residual { score -= 0.3; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, post_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize if no items can fit in the current bin
    if fitting_bins_count == 0 {
        score -= 1.5;
    }

    // Reward for small post-residuals
    if post_residual < 10 {
        score += 2.0;
    } else if post_residual < 30 {
        score += 1.5;
    }

    // Penalize if the next item is too large to fit in half of the remaining space
    if next_item_size > 0 && post_residual + next_item_size <= bin_capacity / 2 {
        score -= 1.2;
    }

    // Reward for using open bins efficiently
    score += (open_bins_count as f64 * total_items as f64).sqrt() / total_items as f64;

    // Penalize if the post-residual is less than the next item size
    if post_residual < next_item_size {
        score -= 1.0;
    }

    // Reward if the post-residual is close to the mean residual
    if post_residual > mean_residual * 2.0 {
        score += 0.5;
    }

    // Penalize if the bin is almost full but not fitting any item
    if bin_capacity - bin_residual < next_item_size && next_item_size > 0 {
        score -= 1.0;
    }

    // New mutation: Reward for having a post-residual that is a multiple of the mean residual
    if post_residual % mean_residual as u32 == 0 {
        score += 0.5;
    }

    // New mutation: Penalize if the next item size is close to the bin capacity
    if next_item_size > bin_capacity / 4 && next_item_size < bin_capacity * 3 / 4 {
        score -= 1.0;
    }

    // Additional mutation: Reward for a high ratio of post-residual to mean residual
    if post_residual > mean_residual * 1.5 {
        score += 0.3;
    }

    // Additional mutation: Penalize if the next item size is very close to the bin capacity
    if next_item_size > bin_capacity * 7 / 8 {
        score -= 1.5;
    }

    score
}

