pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Capacity utilization score
    score += (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 1.5;

    // Penalize if no bins fit the item
    if fitting_bins_count == 0 {
        score -= 2.0;
    }

    // Reward for small post-residuals
    if post_residual < 5 {
        score += 3.0;
    } else if post_residual < 15 {
        score += 1.5;
    } else if post_residual < 30 {
        score += 0.5;
    }

    // Penalize large next items that don't fit well
    if next_item_size > 0 && post_residual + next_item_size > bin_capacity / 2 {
        score -= 2.0;
    }

    // Reward for using open bins efficiently
    score += (open_bins_count as f64 / total_items as f64) * 3.0;

    // Penalize if the residual is smaller than the next item size
    if post_residual < next_item_size {
        score -= 2.0;
    }

    // Reward for residuals close to the mean
    if post_residual > mean_residual / 3.0 && post_residual < mean_residual * 1.5 {
        score += 1.0;
    } else if post_residual > mean_residual * 1.5 && post_residual < mean_residual * 2.5 {
        score += 0.5;
    }

    // Penalize for large open bins
    if open_bins_count > total_items / 4 {
        score -= 1.0;
    }

    score
}
